// Dealzy social sharing card. Embedded so this image can be served by Vercel without a binary asset upload.
const image = Buffer.from('', 'base64');

module.exports = function socialPreview(req, res) {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.setHeader('Allow', 'GET, HEAD');
    return res.status(405).end();
  }
  res.setHeader('Content-Type', 'image/jpeg');
  res.setHeader('Content-Length', String(image.length));
  res.setHeader('Cache-Control', 'public, max-age=86400, s-maxage=604800');
  res.status(200).end(req.method === 'HEAD' ? undefined : image);
};
